package com.cosmetic.shopbackend.catalog;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.JdbcTemplate;
import com.cosmetic.shopbackend.brand.*; import com.cosmetic.shopbackend.identity.AccountRole; import com.cosmetic.shopbackend.security.ShopPrincipal; import com.fasterxml.jackson.core.JsonProcessingException; import com.fasterxml.jackson.databind.ObjectMapper; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.math.*; import java.util.*;
@RestController @RequestMapping("/api/products") @Transactional public class CatalogController {
 private final ProductRepository products; private final ProductVariantRepository variants; private final BrandRepository brands; private final ProductUnmappedValueRepository unmapped; private final ObjectMapper mapper; private final JdbcTemplate jdbc;
 public CatalogController(ProductRepository p,ProductVariantRepository v,BrandRepository b,ProductUnmappedValueRepository u,ObjectMapper m,JdbcTemplate jdbc){products=p;variants=v;brands=b;unmapped=u;mapper=m;this.jdbc=jdbc;}
 @GetMapping public List<ProductSummary> list(){return products.findByStatus(Product.Status.ACTIVE).stream().filter(this::visible).map(p->summary(p)).toList();}
 @GetMapping("/{id}") public ProductDetail get(@PathVariable String id){Product p=products.findById(id).filter(this::visible).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));return detail(p);}
 public record ProductRequest(@NotBlank String brandId,@NotBlank String categoryId,@NotBlank String productName,@NotBlank String secondaryCategory,@NotBlank String tertiaryCategory,List<String> highlights,@NotBlank String ingredients,@NotNull @DecimalMin("1") BigDecimal priceKrw,String primaryImageUrl,Map<String,Object> description){}
 public record ProductSummary(String productId,String brandId,String brandName,String categoryId,String productName,String secondaryCategory,String tertiaryCategory,BigDecimal priceKrw,String priceBin,BigDecimal rating,Integer lovesCount,String primaryImageUrl,List<String> highlights){}
 public record VariantView(String variantId,String skuId,String label,String size,BigDecimal priceKrw,BigDecimal salePriceKrw,String status){}
 public record ProductDetail(ProductSummary product,List<VariantView> variants,String ingredients,Map<String,Object> description){}
 @PostMapping public ResponseEntity<ProductDetail> create(@AuthenticationPrincipal ShopPrincipal actor,@Valid @RequestBody ProductRequest r){requireOwner(actor,r.brandId());validate(r);Product p=new Product(UUID.randomUUID().toString(),r.brandId(),r.categoryId(),r.productName());p.update(input(r),defaultRating(r.tertiaryCategory()));p=products.save(p);saveUnmapped(p.getId(),r.highlights());variants.save(new ProductVariant(UUID.randomUUID().toString(),p.getId(),"SKU-"+UUID.randomUUID().toString().substring(0,8),"기본 옵션",r.priceKrw(),null));return ResponseEntity.status(HttpStatus.CREATED).body(detail(p));}
 @PutMapping("/{id}") public ProductDetail update(@AuthenticationPrincipal ShopPrincipal actor,@PathVariable String id,@Valid @RequestBody ProductRequest r){Product p=products.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));requireOwner(actor,p.getBrandId());validate(r);p.update(input(r),defaultRating(r.tertiaryCategory()));Product saved=products.save(p);saveUnmapped(saved.getId(),r.highlights());variants.findFirstByProductIdAndLabel(saved.getId(),"기본 옵션").ifPresent(v->{v.updateBasePrice(r.priceKrw());variants.save(v);});return detail(saved);}
 @PatchMapping("/{id}/status") public Product status(@AuthenticationPrincipal ShopPrincipal actor,@PathVariable String id,@RequestParam Product.Status value){Product p=products.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));requireOwner(actor,p.getBrandId());p.status(value);return products.save(p);}
 private ProductContract.ProductInput input(ProductRequest r){try{return new ProductContract.ProductInput(r.productName(),r.categoryId(),r.secondaryCategory(),r.tertiaryCategory(),r.highlights()==null?List.of():r.highlights(),r.ingredients(),r.priceKrw(),r.primaryImageUrl(),r.description==null?null:mapper.writeValueAsString(r.description));}catch(JsonProcessingException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"description 형식이 올바르지 않습니다");}}
 private void validate(ProductRequest r){if(!ProductContract.SECONDARY.contains(r.secondaryCategory())||!ProductContract.TERTIARY.contains(r.tertiaryCategory()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"카테고리가 계약 어휘에 없습니다");if(jdbc.queryForObject("select count(*) from category where category_id=? and is_active=true",Integer.class,r.categoryId())==0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"활성 카테고리가 아닙니다");}
 private BigDecimal defaultRating(String tertiary){List<BigDecimal> scoped=products.ratingsByTertiary(tertiary);List<BigDecimal> values=scoped.size()>=3?scoped:products.allRatings();if(values.isEmpty())return BigDecimal.valueOf(4.0);values=new ArrayList<>(values);values.sort(Comparator.naturalOrder());int n=values.size(),mid=n/2;return n%2==1?values.get(mid):values.get(mid-1).add(values.get(mid)).divide(BigDecimal.valueOf(2),2,RoundingMode.HALF_UP);}
 private void saveUnmapped(String productId,List<String> values){for(String value:values==null?List.<String>of():values)if(!ProductContract.isKnownHighlight(value))unmapped.save(new ProductUnmappedValue(productId,"highlights",value));}
 private void requireOwner(ShopPrincipal actor,String brandId){if(actor==null||actor.role()!=AccountRole.SELLER||brands.findByIdAndSeller_Id(brandId,actor.accountId()).isEmpty())throw new ResponseStatusException(HttpStatus.FORBIDDEN);}
 private boolean visible(Product p){return p.getStatus()==Product.Status.ACTIVE&&brands.findById(p.getBrandId()).map(b->b.getStatus()==BrandStatus.ACTIVE).orElse(false);}
 private ProductSummary summary(Product p){Brand b=brands.findById(p.getBrandId()).orElse(null);BigDecimal price=variants.findByProductId(p.getId()).stream().filter(v->v.getStatus()==ProductVariant.Status.ACTIVE).map(ProductVariant::unitPrice).filter(Objects::nonNull).min(Comparator.naturalOrder()).orElse(null);return new ProductSummary(p.getId(),p.getBrandId(),b==null?null:b.getName(),p.getCategoryId(),p.getName(),p.getSecondaryCategory(),p.getTertiaryCategory(),price,p.getPriceBin(),p.getRating(),p.getLovesCount(),p.getPrimaryImageUrl(),new ArrayList<>(p.getHighlights()));}
 private ProductDetail detail(Product p){Map<String,Object> d=null;try{if(p.getDescriptionJson()!=null)d=mapper.readValue(p.getDescriptionJson(),Map.class);}catch(Exception ignored){}List<VariantView> vs=variants.findByProductId(p.getId()).stream().filter(v->v.getStatus()==ProductVariant.Status.ACTIVE).map(v->new VariantView(v.getId(),v.getSku(),v.getLabel(),v.getSize(),v.getPrice(),v.getSalePrice(),v.getStatus().name())).toList();return new ProductDetail(summary(p),vs,p.getIngredientsText(),d);}
}
